import { NodeCompatibleFileSystemAdapter, } from "../shared/node-filesystem-adapter.js";
import { isDirectConstruction, markNativeFileSystemAdapter, } from "../../native-file-system-provenance.js";
import { serverLogger } from "../../../../utils/index.js";
/** Node.js filesystem adapter. */
export class NodeFileSystemAdapter extends NodeCompatibleFileSystemAdapter {
    constructor(options = {}) {
        super(serverLogger, options);
        if (isDirectConstruction(this, NodeFileSystemAdapter)) {
            markNativeFileSystemAdapter(this);
        }
    }
    async exists(path) {
        try {
            return await super.exists(path);
        }
        catch (error) {
            serverLogger.debug(`File access check failed for ${path}:`, { error });
            throw error;
        }
    }
}
